    tools: &[std::sync::Arc<dyn crate::Tool<Ctx>>],
    run_ctx: &crate::RunContext<Ctx>,
    tool_ctx: &crate::ToolContext<Ctx>,
    call: &crate::ToolCallRequest,
) -> (crate::ToolCallOutcome, Option<crate::AgentEvent>)
where
    Ctx: Send + Sync + 'static,
{
