    inner: S,
    model: Arc<dyn Model>,
    counter: Arc<dyn TokenCounter>,
    threshold: usize,
    settings: ModelSettings,
    prompt: String,
    cheap_estimate: AtomicUsize,
    compacting: AtomicBool,
}

