/// just `RunFailed`.
fn append_synthetic_terminal(events: &mut Vec<AgentEvent>, event: Option<AgentEvent>) {
    if let Some(event) = event {
        if !events.last().is_some_and(AgentEvent::is_terminal) {
            events.push(event);
        }
    }
}

